import { SelectBetView } from "./SelectBetView";
import StoreManager from '../../store/StoreManager';
import { ORIENTATION, VIEWMAP } from "../../store/StoreMap";
import { instantiate, Label, Node, Toggle } from "cc";
import AppAssetBundle from "../../utils/AppAssetBundle";
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../../events/GameRuntimeEventBus';
import GameConfigManager from '../../config/GameConfigManager';

export default class SelectBetViewModel {
    selectBetView: SelectBetView;
    storeManager: StoreManager;
    itemList: Node[] = [];
    assetBundle: AppAssetBundle;
    constructor(context: SelectBetView) {
        this.selectBetView = context;
        this.storeManager = StoreManager.getInstance();
        this.assetBundle = AppAssetBundle.getInstance(GameConfigManager.GAMEID);
        this.initItem();
        this.registerReactions();
    }
    registerReactions() {
        // mobx 移除計劃：DeviceStore.orientation 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.selectBetView.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED,
            (e) => this.orientation(e.orientation));
        // 原本 fireImmediately: false，這裡不用手動呼叫一次
    }
    orientation(orientation) {
        console.log('[selectBetView] orientation = ', orientation);
        if (this.selectBetView.node.active) {
            console.log('change selectBetView orientation');
            this.storeManager.getViewStore().selectBetView(orientation);
        }

    }
    async initItem() {
        if (this.storeManager.getDeviceStore().orientation == ORIENTATION.LANDSCAPE) {
            this.selectBetView.setStyle(0);
        } else {
            this.selectBetView.setStyle(-250);
        }
        let gameInitData = this.storeManager.getGameStore().gameInitData;
        let betLevels = gameInitData['machine_info']['bet_level'];
        for (let index = 0; index < betLevels.length; index++) {
            const betLevel = betLevels[index];
            const item = instantiate(await this.assetBundle.loadPrefab(VIEWMAP.SELECTBETITEM.path));
            item.getChildByName('Amount').getComponent(Label).string = `${StoreManager.getInstance().getGameStore().formatAmount(betLevel)}`;
            const toggle = item.getChildByName('Toggle').getComponent(Toggle);
            if (betLevel === this.storeManager.getModel("TemplateStore").betBalance) {
                toggle.isChecked = true;
            }
            item.on(Node.EventType.TOUCH_START, () => {
                this.onItemClick(toggle, toggle.isChecked, index);
            }, this);
            this.selectBetView.addItem(item);
            this.itemList.push(item);
        }
    }
    onItemClick(toggle, isChecked, index) {
        if (isChecked) return;
        this.itemList.forEach((item, i) => {
            if (i === index) {
                this.selectBetView.setSeclectState(item);
                this.storeManager.getModel("TemplateStore").changeBetIndex(index);
                return;
            }
            this.selectBetView.setDefaultState(item);
        });

    }

}
