import { sys } from 'cc';

interface DownloadEntry {
    url: string;
    time: number;
}

// 攔截 XMLHttpRequest.open 記錄實際發出的 HTTP 請求
// Cocos 內部用 XMLHttpRequest 下載 不走 downloader.downloadFile 實例屬性
let downloadLog: DownloadEntry[] = [];
let originalXHROpen: typeof XMLHttpRequest.prototype.open | null = null;

export function startDownloadLog(): void {
    if (sys.isNative) return;
    downloadLog = [];
    if (originalXHROpen) return;
    originalXHROpen = XMLHttpRequest.prototype.open;
    const log = downloadLog;
    const original = originalXHROpen;
    XMLHttpRequest.prototype.open = function (this: XMLHttpRequest, ...args: any[]) {
        const url = args[1];
        if (typeof url === 'string') {
            log.push({ url, time: Date.now() });
        }
        return original.apply(this, args as any);
    } as typeof XMLHttpRequest.prototype.open;
}

export function stopDownloadLog(label: string): void {
    if (sys.isNative) return;
    if (originalXHROpen) {
        XMLHttpRequest.prototype.open = originalXHROpen;
        originalXHROpen = null;
    }
    const log = downloadLog;
    console.info(`[DownloadLogger] ===== ${label} 下載統計: ${log.length} 個 HTTP 請求 =====`);
    for (const entry of log) {
        console.info(`[DownloadLogger]   ${entry.url}`);
    }
    console.info(`[DownloadLogger] ===== 下載統計結束 =====`);
    downloadLog = [];
}
